#!/usr/bin/env python3
import json
from pathlib import Path

root = Path(__file__).resolve().parents[3]
contract = json.loads((root / "packages/openapi/openapi.yaml").read_text())
paths = sorted(contract["paths"].keys())

ts_path = root / "packages/shared-contracts/src/openapi-paths.ts"
ts_path.parent.mkdir(parents=True, exist_ok=True)
ts_lines = [
    "// Generated by packages/openapi/scripts/generate-contracts.py; do not edit.\n",
    "export const openApiPaths = [\n",
]
for path in paths:
    ts_lines.append(f"  {json.dumps(path)},\n")
ts_lines.append("] as const;\n")
ts_lines.append("export type OpenApiPath = (typeof openApiPaths)[number];\n")
ts_path.write_text("".join(ts_lines))

swift_path = root / "apps/ios/Generated/OpenAPIPaths.swift"
swift_path.parent.mkdir(parents=True, exist_ok=True)
swift_lines = [
    "// Generated by packages/openapi/scripts/generate-contracts.py; do not edit.\n",
    "public enum OpenAPIPaths {\n",
    "    public static let all: [String] = [\n",
]
for path in paths:
    swift_lines.append(f"        {json.dumps(path)},\n")
swift_lines.extend(["    ]\n", "}\n"])
swift_path.write_text("".join(swift_lines))
